"""Append rendered torch clips without altering the existing sprite animations."""
import json
import re
from pathlib import Path

folder = Path(__file__).resolve().parents[1] / 'art/sprites/mc/model'
metadata = json.loads((folder / 'torch_hands.json').read_text())
(folder / 'torch_hand_positions.gd').write_text(
    'extends RefCounted\n## Hand anchors in source-frame pixels, generated by the renderer.\nconst HANDS = {\n'
    + ',\n'.join('    &"' + clip + '": [' + ', '.join(f'Vector2({x}, {y})' for x, y in info['hands']) + ']' for clip, info in metadata.items())
    + '\n}\n')
path = folder / 'mc_frames.tres'
text = path.read_text()
if 'name": &"torch_idle"' in text:
    print('Torch clips already added; hand positions refreshed.')
    raise SystemExit(0)
resources, animations = [], []
for clip, info in metadata.items():
    resources.append(f'[ext_resource type="Texture2D" path="res://art/sprites/mc/model/mc_{clip}.png" id="{clip}"]\n')
    frames = []
    for i in range(info['frames']):
        ident = f'{clip}_{i}'
        resources.append(f'[sub_resource type="AtlasTexture" id="{ident}"]\natlas = ExtResource("{clip}")\nregion = Rect2({i % 8 * 256}, {i // 8 * 240}, 256, 240)\n')
        frames.append('{"duration": 1.0, "texture": SubResource("' + ident + '")}')
    animations.append('{\n"frames": [' + ',\n'.join(frames) + f'],\n"loop": true,\n"name": &"{clip}",\n"speed": 24.0\n' + '}')
text = text.replace('[resource]', '\n'.join(resources) + '\n[resource]', 1)
# Godot requires all external resources before the first subresource.
external = re.findall(r'\[ext_resource[^\n]+\]\n', text)
text = re.sub(r'\[ext_resource[^\n]+\]\n', '', text)
text = text.replace('[sub_resource', '\n'.join(external) + '\n[sub_resource', 1)
text = text.rstrip()[:-1] + ',\n' + ',\n'.join(animations) + ']\n'
text = re.sub(r'load_steps=\d+', f'load_steps={141 + sum(x["frames"] for x in metadata.values()) + 3}', text, count=1)
# Godot requires all external resources before sub-resources.
external = re.findall(r'\[ext_resource[^\n]*\]\n', text)
text = re.sub(r'\[ext_resource[^\n]*\]\n', '', text)
header_end = text.index('\n') + 1
text = text[:header_end] + '\n' + ''.join(external) + text[header_end:]
path.write_text(text)
